export type FamilyNamespace = keyof typeof DICTIONARIES
export type MessageKeyOf<N extends FamilyNamespace> = keyof (typeof DICTIONARIES)[N]['en']

export function dictionariesFor<N extends FamilyNamespace>(namespace: N): (typeof DICTIONARIES)[N] {
  return DICTIONARIES[namespace]
}

